inline QJsonObject settings(QString family){if(family==families()[0])return {{"shortWindow",5},{"longWindow",20}};if(family==families()[1])return {{"fastWindow",12},{"slowWindow",26},{"signalWindow",9}};if(family==families()[2])return {{"rsiPeriod",14},{"entryThreshold",30},{"exitThreshold",70}};if(family==families()[3])return {{"breakoutWindow",20},{"volumeMultiplier",1.5},{"breakoutMargin",.005},{"minCloseLocation",.7}};return {{"positionLookbackWindow",120},{"maxRangePosition",.35},{"volumeWindow",20},{"volumeMultiplier",1.8},{"maxAbsReturn",.02},{"maxIntradayRange",.06},{"minCloseLocation",.5}};}
