inline int validateSettings(QString f,const QJsonObject&s){auto w=[&](QString k){return int(number(s,k,1,250,true));};auto p=[&](QString k){return number(s,k,.001,1);};if(f==families()[0]){int a=w("shortWindow"),b=w("longWindow");need(a<b,"短均线必须小于长均线");return b+1;}if(f==families()[1]){int a=w("fastWindow"),b=w("slowWindow"),c=w("signalWindow");need(a<b,"快线必须小于慢线");return b+c;}if(f==families()[2]){int a=w("rsiPeriod");need(number(s,"entryThreshold",.001,99)<number(s,"exitThreshold",.001,100),"RSI进入阈值必须小于退出阈值");return a+1;}if(f==families()[3]){int a=w("breakoutWindow");number(s,"volumeMultiplier",1,20);p("breakoutMargin");p("minCloseLocation");return a+1;}need(f==families()[4],"未知策略");int a=w("positionLookbackWindow"),b=w("volumeWindow");number(s,"volumeMultiplier",1,20);for(auto k:{"maxRangePosition","maxAbsReturn","maxIntradayRange","minCloseLocation"})p(k);return std::max(a,b)+1;}
