struct Bar{QString date,code,name;double open,high,low,close,volume;};
inline QMap<QString,QVector<Bar>> readBars(const QJsonObject&d){quantParquet::verifySelection(d);legacyEvidence(d);need(d.value("schema")=="quant-native-dataset/v1","不是本机数据包");for(auto k:{"datasetId","source","adjustmentMode","membershipMode"})need(d.value(k).isString()&&!d.value(k).toString().trimmed().isEmpty(),QString("缺少数据身份/来源: ")+k);QString asOf=d.value("asOf").toString();need(QDate::fromString(asOf,Qt::ISODate).isValid()&&asOf.size()==10,"asOf日期无效");auto a=d.value("bars").toArray();need(a.size()>0&&a.size()<=100000,"数据包需要1–100000行完整日线，未隐式截断");QMap<QString,QVector<Bar>> out;QSet<QString>keys;QRegularExpression code("^[0-9]{6}$");for(auto v:a){need(v.isObject(),"日线不是对象");auto o=v.toObject();Bar b;b.code=o.value("code").toString();b.name=o.value("name").toString();b.date=o.value("date").toString();need(code.match(b.code).hasMatch()&&!b.name.isEmpty(),"需要明确六位代码和名称；不推断交易所");need(b.date.size()==10&&QDate::fromString(b.date,Qt::ISODate).isValid()&&b.date<=asOf,"日线日期无效或超过asOf");auto key=b.code+":"+b.date;need(!keys.contains(key),"重复代码/日期日线");keys.insert(key);b.open=number(o,"open",.000001,1e9);b.high=number(o,"high",.000001,1e9);b.low=number(o,"low",.000001,1e9);b.close=number(o,"close",.000001,1e9);b.volume=number(o,"volume",0,1e18);need(b.high>=std::max(b.open,b.close)&&b.low<=std::min(b.open,b.close)&&b.high>=b.low,"OHLC范围不一致");out[b.code].append(b);}need(out.size()<=1200,"本机数据包最多1200个证券");for(auto it=out.begin();it!=out.end();++it)std::sort(it->begin(),it->end(),[](const Bar&a,const Bar&b){return a.date<b.date;});return out;}
