inline double commission(double gross,const QJsonObject&c){return gross>0?std::max(gross*c.value("commissionBps").toDouble()/10000,c.value("minimumCommission").toDouble()):0;}
inline double exitValue(int shares,double close,const QJsonObject&c){double gross=shares*close*(1-c.value("slippageBps").toDouble()/10000);return shares?gross-commission(gross,c)-gross*c.value("stampDutyBps").toDouble()/10000:0;}
